import 'package:flutter/material.dart'; import '../services/settings_service.dart'; import 'home_screen.dart';
class LockScreen extends StatefulWidget {const LockScreen({super.key});@override State<LockScreen> createState()=>_LockScreenState();}
class _LockScreenState extends State<LockScreen>{final pin=TextEditingController();String error='';Future<void> unlock()async{if(await SettingsService.verify(pin.text)){if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const HomeScreen()));}else{setState(()=>error='رمز الدخول غير صحيح');pin.clear();}}
@override Widget build(BuildContext c)=>Scaffold(body:Center(child:Padding(padding:const EdgeInsets.all(28),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[const Icon(Icons.blur_on,size:80,color:Color(0xFF69E8FF)),const Text('CHRONOX',style:TextStyle(fontSize:30,letterSpacing:7)),const Text('SECURE ACCESS',style:TextStyle(color:Color(0xFF69E8FF),letterSpacing:3)),const SizedBox(height:30),TextField(controller:pin,obscureText:true,keyboardType:TextInputType.number,textAlign:TextAlign.center,decoration:const InputDecoration(hintText:'PIN')),Text(error,style:const TextStyle(color:Colors.redAccent)),const SizedBox(height:12),FilledButton(onPressed:unlock,child:const Text('UNLOCK SYSTEM'))]))));
}